def transform(grid):
    g = np.array(grid)
    H, W = g.shape
    mask = g == 0
    known = ~mask

    def ok(py, px):
        seen = {}
        for y in range(H):
            for x in range(W):
                if known[y, x]:
                    k = (y % py, x % px)
                    if k in seen and seen[k] != g[y, x]:
                        return None
                    seen[k] = g[y, x]
        return seen

    best = None
    for s in range(2, H + W + 1):
        for py in range(1, H + 1):
            px = s - py
            if px < 1 or px > W:
                continue
            seen = ok(py, px)
            if seen is not None and all(((y % py, x % px) in seen)
                                        for y, x in zip(*np.nonzero(mask))):
                best = (py, px, seen)
                break
        if best:
            break

    py, px, seen = best
    full = g.copy()
    for y, x in zip(*np.nonzero(mask)):
        full[y, x] = seen[(y % py, x % px)]
    emit(full, f"Pattern repeats every {py} rows and {px} columns; fill the 0-masked cells from the repeat.")

    y0, x0, y1, x1 = bbox(list(zip(*np.nonzero(mask))))
    out = full[y0:y1 + 1, x0:x1 + 1].copy()
    emit(out, "Crop the restored region that was hidden under the 0 block.")
    return out
